function findScore(nums) {
  const n = nums.length;
  const order = Array.from({ length: n }, (_, i) => i);
  order.sort((a, b) => nums[a] - nums[b] || a - b);
  const marked = new Array(n).fill(false);
  let score = 0;

  for (const i of order) {
    if (marked[i]) {
      continue;
    }
    score += nums[i];
    marked[i] = true;
    if (i > 0) marked[i - 1] = true;
    if (i + 1 < n) marked[i + 1] = true;
  }
  return score;
}

