function findScore(nums) {
  const done = nums.map(() => false);
  let total = 0;
  while (true) {
    let pickIndex = -1;
    for (let j = 0; j < nums.length; j++) {
      if (done[j]) continue;
      if (pickIndex === -1 || nums[j] < nums[pickIndex]) pickIndex = j;
    }
    if (pickIndex === -1) break;
    total += nums[pickIndex];
    for (let d = -1; d <= 1; d++) {
      const j = pickIndex + d;
      if (j >= 0 && j < nums.length) done[j] = true;
    }
  }
  return total;
}

