function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? pick(1500, 2000) : pick(1, 9);
  const roll = rand();
  let top;
  if (roll < 0.4) top = size === 'large' ? 50 : 3;
  else if (roll < 0.6) top = 1;
  else top = 1000000;
  const nums = [];
  for (let i = 0; i < n; i++) nums.push(pick(1, top));
  if (rand() < 0.2) nums.sort((a, b) => (roll < 0.8 ? a - b : b - a));
  return [nums];
}
